133: const StreamingMarkdownContent: React.FC<StreamingMarkdownContentProps> =
134:   React.memo(({ content, isStreaming = false, size, browserToolResult }) => {
135:     // Build the remark plugins array - keep default GFM and Math, add citations
136:     const remarkPlugins = React.useMemo(() => {
137:       return [
138:         defaultRemarkPlugins.gfm,
139:         defaultRemarkPlugins.math,
140:         remarkCitationParser,
141:       ];
142:     }, []);
143: 
144:     return (
145:       <div
146:         className={`
147:           max-w-full
148:           ${size === "sm" ? "prose-sm" : size === "lg" ? "prose-lg" : ""}
149:           prose
150:           prose-neutral
151:           prose-headings:font-semibold
152:           prose:text-neutral-800
153:           prose-strong:font-semibold
154:           prose-ul:marker:text-neutral-700
155:           prose-li:marker:text-neutral-700
156:           prose-headings:text-neutral-800
157:           prose-pre:bg-transparent
158:           prose-pre:rounded-xl
159:           prose-pre:text-neutral-800
160:           prose-pre:font-normal
161:           prose-pre:my-0
162:           prose-pre:max-w-full
163:           prose-pre:pt-1
164:           [&_table]:border-collapse
165:           [&_table]:w-full
166:           [&_table]:border
167:           [&_table]:border-neutral-200
168:           [&_table]:rounded-lg
169:           [&_table]:overflow-hidden
170:           [&_th]:px-3
171:           [&_th]:py-2
172:           [&_th]:text-left
173:           [&_th]:font-semibold
174:           [&_th]:border-b
175:           [&_th]:border-r
176:           [&_th]:border-neutral-200
177:           [&_th:last-child]:border-r-0
178:           [&_td]:px-3
179:           [&_td]:py-2
180:           [&_td]:border-r
181:           [&_td]:border-neutral-200
182:           [&_td:last-child]:border-r-0
183:           [&_tbody_tr:not(:last-child)_td]:border-b
184:           [&_code:not(pre_code)]:text-neutral-700
185:           [&_code:not(pre_code)]:bg-neutral-100
186:           [&_code:not(pre_code)]:font-normal
187:           [&_code:not(pre_code)]:px-1.5
188:           [&_code:not(pre_code)]:py-0.5
189:           [&_code:not(pre_code)]:rounded-md
190:           [&_code:not(pre_code)]:text-[90%]
191:           [&_code:not(pre_code)]:before:hidden
192:           [&_code:not(pre_code)]:after:hidden
193:           dark:prose-invert
194:           dark:prose:text-neutral-200
195:           dark:prose-pre:bg-none
196:           dark:prose-headings:text-neutral-200
197:           dark:prose-strong:text-neutral-200
198:           dark:prose-pre:text-neutral-200
199:           dark:prose:pre:text-neutral-200
200:           dark:[&_table]:border-neutral-700
201:           dark:[&_thead]:bg-neutral-800
202:           dark:[&_th]:border-neutral-700
203:           dark:[&_td]:border-neutral-700
204:           dark:[&_code:not(pre_code)]:text-neutral-200
205:           dark:[&_code:not(pre_code)]:bg-neutral-800
206:           dark:[&_code:not(pre_code)]:font-normal
207:           dark:prose-ul:marker:text-neutral-300
208:           dark:prose-li:marker:text-neutral-300
209:           break-words
210:         `}
211:       >
212:         <StreamingMarkdownErrorBoundary
213:           content={content}
214:           isStreaming={isStreaming}
215:         >
216:           <Streamdown
217:             parseIncompleteMarkdown={isStreaming}
218:             isAnimating={isStreaming}
219:             rehypePlugins={safeRehypePlugins}
220:             remarkPlugins={remarkPlugins}
221:             controls={false}
222:             components={{
223:               img: ({ alt }: React.ImgHTMLAttributes<HTMLImageElement>) =>
224:                 alt ? <span>{alt}</span> : null,
225:               pre: CodeBlock,
226:               table: ({
227:                 children,
228:                 ...props
229:               }: React.HTMLAttributes<HTMLTableElement>) => (
230:                 <div className="overflow-x-auto max-w-full">
231:                   <table
232:                     {...props}
233:                     className="border-collapse w-full border border-neutral-200 dark:border-neutral-700 rounded-lg overflow-hidden"
234:                   >
235:                     {children}
236:                   </table>
237:                 </div>
238:               ),
239:               // @ts-expect-error: custom citation type
240:               "ol-citation": ({
241:                 cursor,
242:               }: {
243:                 cursor: number;
244:                 start: number;
245:                 end: number;
246:               }) => {
247:                 const pageStack = browserToolResult?.page_stack;
248:                 const hasValidPage = pageStack && cursor < pageStack.length;
249:                 const pageUrl = hasValidPage ? pageStack[cursor] : null;
250: 
251:                 const getPageTitle = (url: string) => {
252:                   if (url.startsWith("search_results_")) {
253:                     const searchTerm = url.substring("search_results_".length);
254:                     return `Search: ${searchTerm}`;
255:                   }
256:                   try {
257:                     const urlObj = new URL(url);
258:                     return urlObj.hostname;
259:                   } catch {
260:                     return url;
261:                   }
262:                 };
263: 
264:                 const citationElement = (
265:                   <span className="text-xs text-neutral-500 dark:text-neutral-400 bg-neutral-100 dark:bg-neutral-800 rounded-full px-2 py-1 ml-1">
266:                     [{cursor}]
267:                   </span>
268:                 );
269: 
270:                 if (pageUrl && pageUrl.startsWith("http")) {
271:                   return (
272:                     <a
273:                       href={pageUrl}
274:                       target="_blank"
275:                       rel="noopener noreferrer"
276:                       className="inline-flex items-center hover:opacity-80 transition-opacity no-underline"
277:                       title={getPageTitle(pageUrl)}
278:                     >
279:                       {citationElement}
280:                     </a>
281:                   );
282:                 }
283: 
284:                 return citationElement;
285:               },
286:             }}
287:           >
288:             {content}
289:           </Streamdown>
290:         </StreamingMarkdownErrorBoundary>
291:       </div>
292:     );
293:   });
